WITH filtered AS (SELECT *, ROUND(shipping_fee * 1.07, 2) AS shipping_fee_scaled, COALESCE(channel, 'NONE') AS resolved_channel FROM orders WHERE customer_id IS NOT NULL AND channel = 'web') SELECT DATE_TRUNC('YEAR', order_date) AS year_start, MAX(amount) AS max_amount, COUNT(*) FILTER (WHERE status = 'PENDING') AS pending_rows, COUNT(*) AS event_count FROM filtered GROUP BY year_start HAVING pending_rows > 1
